<?php
 namespace App\Http\Controllers; use App\Models\Payment; use App\Models\Sale; use Illuminate\Http\Request; class PaymentController extends Controller { public function store(Request $request) { $data = $request->validate([ 'sale_id' => 'required|exists:sales,id', 'amount' => 'required|numeric|min:1', 'date' => 'required|date', 'note' => 'nullable|string|max:255', ]); $sale = Sale::findOrFail($data['sale_id']); Payment::create([ 'sale_id' => $sale->id, 'due_date' => $data['date'], 'amount' => $data['amount'], 'status' => 'paid', 'paid_at' => $data['date'], 'note' => $data['note'] ?? 'Pembayaran Fleksibel', ]); $this->recalculateSale($sale); return redirect()->route('penjualan.show', $sale)->with('success', 'Pembayaran fleksibel berhasil dicatat.'); } public function update(Request $request, Payment $payment) { $payment->status = 'paid'; $payment->paid_at = now(); $payment->save(); $sale = $payment->sale; $this->recalculateSale($sale); return redirect()->route('penjualan.show', $sale)->with('success', 'Pembayaran berhasil dicatat.'); } private function recalculateSale(Sale $sale): void { $paidFromPayments = $sale->payments()->where('status', 'paid')->sum('amount'); $dpRecorded = $sale->payments()->where('note', 'Down Payment')->exists(); $dpBuffer = $dpRecorded ? 0 : $sale->down_payment; $sale->paid_amount = min($sale->price, $paidFromPayments + $dpBuffer); $sale->outstanding_amount = max(0, $sale->price - $sale->paid_amount); $sale->status = $sale->outstanding_amount <= 0 ? 'paid_off' : 'active'; $sale->save(); } } 